insert into volumes (id, title_ml) values (2, 'വാല്യം 2') on conflict (id) do nothing;
insert into articles (volume_id, section_no, title_ml, start_page, end_page) values (2, 1, 'ആമുഖമായി', '47', '48');
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 1, 'paragraph', 'ഇസ്ലാമിന്റെ രണ്ടടിസ്ഥാനങ്ങൾ ഖുർആനും ഹദീസുമാണല്ലോ. ഖുർആൻ പരിഭാഷകൾ ലഭ്യമാണെങ്കിലും ഹദീസ് പരിഭാഷകൾ വേണ്ടത്ര ലഭ്യമല്ല. പലേടത്തും ബുഖാരീ, മുസ്ലിം, എന്നീ ഹദീസ് ഗ്രന്ഥങ്ങൾ കാണുമെങ്കിലും മറ്റു ഹദീസ് ഗ്രന്ഥങ്ങൾ പലപ്പോഴും ലഭ്യമായിരിക്കയില്ല. ലഭ്യമായാൽ തന്നെ അവ വായിച്ചു മനസ്സിലാക്കാൻ കഴിയുന്നവർ ചുരുക്കമാണ്. ഈ സാഹചര്യത്തിൽ നബിയെ സ്നേഹിക്കുന്നവർക്ക്, നബിചര്യ ദൈനംദിന ജീവിതത്തിൽ പകർത്താനാഗ്രഹിക്കുന്നവർക്ക് ഹദീസുകൾ എത്തിക്കണമെന്ന ആഗ്രഹത്തിൽ നിന്നാണ് ഈ കൃതി രൂപം കൊണ്ടത്.', null, '47' from articles where volume_id=2 and section_no=1;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 2, 'paragraph', '"റസൂൽ(സ) നിങ്ങൾക്ക് നൽകിയതെന്തോ അത് നിങ്ങൾ സ്വീകരിക്കുക. ഏതൊന്നിൽ നിന്ന് അവിടന്ന് നിങ്ങളെ വിലക്കിയോ അത് നിങ്ങൾ വെടിയുകയും ചെയ്യുക." (ഖുർആൻ 59:7)', null, '47' from articles where volume_id=2 and section_no=1;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 3, 'paragraph', '"തീർച്ചയായും അല്ലാഹുവിന്റെ ദൂതനിൽ നിങ്ങൾക്ക് ഉത്തമ മാതൃകയുണ്ട്." (ഖുർആൻ 33:21)', null, '47' from articles where volume_id=2 and section_no=1;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 4, 'paragraph', 'നബി(സ) പറഞ്ഞു: "ഞാൻ രണ്ടു കാര്യങ്ങൾ നിങ്ങൾക്കായി ബാക്കിവെച്ചാണ് പോകുന്നത്. അവ രണ്ടും മുറുകെ പിടിച്ചാൽ നിങ്ങൾ ഒരിക്കലും പിഴച്ചുപോകില്ല. അല്ലാഹുവിന്റെ ഗ്രന്ഥവും പ്രവാചക ചര്യയുമത്രെ അത്." (മുവത്വ)', null, '47' from articles where volume_id=2 and section_no=1;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 5, 'paragraph', '(നബിയേ) നിങ്ങൾ പറയുക: "നിങ്ങൾ അല്ലാഹുവിനെ സ്നേഹിക്കുന്നുവെങ്കിൽ എന്നെ പിന്തുടരുക. അല്ലാഹു നിങ്ങളെയും സ്നേഹിക്കും." (ഖുർആൻ)', null, '47' from articles where volume_id=2 and section_no=1;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 6, 'paragraph', '''ഹദീസ് വിജ്ഞാനകോശം'' മതവിധികൾ യഥാവിധി മനസ്സിലാക്കാൻ സഹായിക്കുന്നു. ഇസ്ലാമിനെക്കുറിച്ച് അതിന്റെ ഉറവിടങ്ങളിൽ നിന്നുതന്നെ കൂടുതൽ അടുത്തറിയാൻ ഇതുപകരിക്കും. മതകർമ്മങ്ങൾ ചെയ്യുമ്പോൾ അതിന്റെ അടിസ്ഥാനം എന്താണെന്ന് നാം അറിഞ്ഞിരിക്കണം. നിലവിലുള്ള മിക്ക ഹദീസ് ഗ്രന്ഥങ്ങളും പല രൂപത്തിലാണ് ക്രോഡീകരിക്കപ്പെട്ടിട്ടുള്ളത്. അതുപോലെ ഹദീസുകളിൽ ഉപയോഗിക്കുന്ന പല പദങ്ങളും ഇപ്പോൾ പ്രയോഗത്തിൽ ഇല്ലാത്തതുകൊണ്ട് പല ഹദീസുകളുടെയും അർത്ഥം മനസ്സിലാക്കാൻ പ്രയാസമാണ്.', null, '47' from articles where volume_id=2 and section_no=1;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 7, 'paragraph', 'ബുഖാരീ, മുസ്ലിം, അബൂദാവൂദ്, തുർമുദി, ഇബ്നു മാജ, നസാഈ എന്നീ ഗ്രന്ഥങ്ങളിലെ ഹദീസുകൾ ആവർത്തനം ഒഴിവാക്കി വിഷയ ക്രമത്തിൽ ക്രോഡീകരിച്ച് മലയാള പരിഭാഷയോടെയാണ് പ്രസിദ്ധീകരിക്കുന്നത്. സിഹാഹുസ്സിത്തയിലെ ഒരുവിഷയത്തിലെ ഹദീസുകൾ മുഴുവൻ ഒന്നിച്ചുകാണാൻ എളുപ്പമായിരിക്കുന്നു. നബിചര്യ മനസ്സിലാക്കാനും ജീവിതത്തിൽ പകർത്താനും ആഗ്രഹിക്കുന്നവർക്ക് ഇത് സഹായകമാകട്ടെ എന്ന് പ്രാർത്ഥിക്കുന്നു.', null, '47' from articles where volume_id=2 and section_no=1;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 8, 'paragraph', 'കേരളത്തിലെ എല്ലാ പള്ളികളിലും വീടുകളിലും ഇതിന്റെ കോപ്പി ഉണ്ടായിരിക്കണമെന്ന് ഞങ്ങൾ ആഗ്രഹിക്കുന്നു. ജാരിയായ സ്വദഖ (മരണാനന്തരവും ലഭിക്കുന്ന പുണ്യം) യായി ഈ ഗ്രന്ഥത്തിന്റെ കഴിയുന്നത്ര കോപ്പികൾ വാങ്ങി പള്ളികളിൽ വഖ്ഫ് ആക്കി വെക്കണമെന്ന് അഭ്യർത്ഥിക്കുന്നു. നിങ്ങളുടെ സ്നേഹിതന്മാർക്ക് നൽകാവുന്ന ഒരു നല്ല സമ്മാനമായും ഹദീസ് വിജ്ഞാന കോശത്തെ ഉപയോഗപ്പെടുത്താവുന്നതാണ്.', null, '47' from articles where volume_id=2 and section_no=1;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 9, 'paragraph', 'ഈ കൃതി തയ്യാറാക്കുന്നതിൽ സഹകരിച്ച എല്ലാവർക്കും അല്ലാഹു മതിയായ പ്രതിഫലം നൽകുമാറാകട്ടെ.', null, '47' from articles where volume_id=2 and section_no=1;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 10, 'paragraph', 'പ്രൊഫ: വി. മുഹമ്മദ് സാഹിബ്, എ. അബ്ദുസ്സലാം സാഹിബ്, പി.എം.കെ. ഫൈസി, ഡോ: അഹ്മദ് ഇസ്മാഈൽ ലബ്ബ, പ്രൊഫ: കെ. ഹബീബ പാഷ, ഡോ: കെ മുഹമ്മദ് ബഷീർ, മുഹമ്മദ് മുജീബ് കാളിയാർ, മുഹമ്മദ് ശരീഫ് വി.പി, ഇ.എം ശരീഫ് മുതുതല, എം.കെ ഹസ്സൻ കോട്ടുമല, വി.എ.എം ഇസ്ഹാഖ് നദ്വി, അബൂബക്കർ പി.കെ, ഉമർ കെ.പി, ഇബ്രാഹീം നദ്വി, എൻ.കെ, ഹുസൈൻ ഷംസുദ്ദീൻ വെളിയംകോട്, അമാനുല്ല എ.കെ, മുഹമ്മദ് അഷ്റഫ് മൗലവി, പ്രൊഫ: മുഹമ്മദ് കുട്ടശ്ശേരി, ഫാറൂഖ് അബ്ദുല്ല നാദാപുരം, ഇ. അബ്ദുൽ ലത്തീഫ്, എം.പി മുഹമ്മദ് ഫൈസൽ അഹ്സനി, അബ്ദുൽ ഖാദർ അഹ്സനി, ഹാരിസ് എം. ഹുദവി, മുഹമ്മദ് അലി ഹുദവി, അൻവർ എ.പി, ശുക്കൂർ.ടി മേലങ്ങം, കബീർ അഞ്ചച്ചവിടി, ഇസ്മാഈൽ എടക്കുളം, റഫീഖ് കെ മമ്പറം, അബ്ദുൽ മജീദ് എൻ.കെ, ഉമൈർ സി.കെ, എം.എ. ആരിഫ, ശുക്കൂർ വള്ളിക്കുന്ന്, സഈദ് കൊട്ടപ്പുറം, ശഫീഖ് സി.പി, റാഷിദ് സി.കെ, കെ. സൈനബ, മൈമൂന സി.കെ, ആരിഫ പി.പി, സൽമ, വി.എം. കുട്ടി മൗലവി, അബൂബക്കർ പോരൂർ, യൂനുസ്.കെ പേങ്ങാട് എന്നിവർ ഈ സംരംഭത്തിൽ സഹകരിച്ചവരാണ്.', null, '47' from articles where volume_id=2 and section_no=1;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 11, 'paragraph', 'ഹദീസ് വിജ്ഞാന കോശം രണ്ടാം വാല്യം തയ്യാറാക്കുന്നതിൽ സഹകരിച്ച ശഫീഖ് വി.കെ എടയാറ്റൂർ, ഉസ്മാൻ പി.വി വേങ്ങൂർ, അശ്റഫ് എം. വെളിമുക്ക്, ഖുബൈബ്. കെ.പി മാരിയാട്, മൻസൂർ എം.പി. ചാപ്പനങ്ങാടി, സുബൈർ ടി.പി. വേങ്ങര, റാഫി.പി. ഇരിങ്ങാട്ടിരി, സ്വാലിഹ് കെ.ടി. കുമരനല്ലൂർ അബ്ദുറഹ്മാൻ മൗലവി പാണ്ടിക്കാട് എന്നിവർക്ക് കൃതജ്ഞത രേഖപ്പെടുത്തുന്നതോടൊപ്പം അവർക്ക് അല്ലാഹു ഉത്തമ പ്രതിഫലം നൽകട്ടെ എന്ന് പ്രാർത്ഥിക്കുകയും ചെയ്യുന്നു. ഈ കൃതി തയ്യാറാക്കുന്നതിൽ സഹകരിച്ച മറ്റു വല്ലവരുടെയും പേരുകൾ വിട്ടുപോയിട്ടുണ്ടെങ്കിൽ ക്ഷമിക്കണമെന്നഭ്യർത്ഥിക്കുന്നു.', null, '48' from articles where volume_id=2 and section_no=1;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 12, 'paragraph', 'വളരെയധികം പ്രയാസപ്പെട്ട് ഇത് പരിശോധിക്കുകയും പ്രൂഫ് നോക്കുകയും ചെയ്ത എന്റെ സഹധർമ്മിണി ഹബീബയെ പ്രത്യേകം അനുസ്മരിക്കുന്നു. അല്ലാഹു അവർക്ക് മതിയായ പ്രതിഫലം നൽകട്ടെ. ബാക്കി ഭാഗങ്ങൾ കൂടി പരിശോധിക്കാനുള്ള ആരോഗ്യം അല്ലാഹു അവർക്ക് പ്രദാനം ചെയ്യട്ടെ എന്ന് പ്രാർത്ഥിക്കുന്നു.', null, '48' from articles where volume_id=2 and section_no=1;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 13, 'paragraph', 'അൽഹംദു ലില്ലാഹ്!', null, '48' from articles where volume_id=2 and section_no=1;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 14, 'paragraph', '"അസ്സിഹാഹുസ്സിത്ത" എന്ന ഹദീസ് വിജ്ഞാനകോശത്തിന്റെ രണ്ടാം വാല്യം തയ്യാറാക്കാനും പ്രസിദ്ധീകരിക്കാനും സഹായിച്ച അല്ലാഹുവിന് സ്തുതി.', null, '48' from articles where volume_id=2 and section_no=1;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 15, 'paragraph', 'ഒന്നാം വാല്യത്തിന്റെ ആമുഖമായി പറഞ്ഞ കാര്യങ്ങൾ രണ്ടാം വാല്യത്തിൽ നിന്നൊഴിവാക്കുകയാണ്. ആദ്യമായി വായിച്ചുതുടങ്ങുന്നവർ ഒന്നാം വാല്യത്തിലെ ആദ്യ ഭാഗങ്ങൾ കൂടി വായിക്കണമെന്നഭ്യർത്ഥിക്കുന്നു.', null, '48' from articles where volume_id=2 and section_no=1;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 16, 'paragraph', 'ഡോ: മുസ്തഫാ കമാൽ പാഷ', null, '48' from articles where volume_id=2 and section_no=1;
